"use client";

import { useState, useEffect, useCallback, useMemo } from "react";
import { axiosClient } from "@/lib/api/axiosClient";
import { useI18n } from "@/i18n/I18nContext";
import { useToast } from "@/components/ui/ToastContext";
import type { SuccessResponse } from "@/types/common";
import type { AdminUserProfile } from "@/app/users/types";

export function useMyProfile() {
  const { lang, setLang } = useI18n();
  const toast = useToast();

  const [profile, setProfile] = useState<AdminUserProfile | null>(null);
  const [themeKey, setThemeKey] = useState<string>("dark");
  const [language, setLanguage] = useState<string>("en");
  const [tableDensity, setTableDensity] = useState<string>("compact");

  const [isLoading, setIsLoading] = useState(true);
  const [isSaving, setIsSaving] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const loadMyProfile = useCallback(async () => {
    setIsLoading(true);
    setError(null);
    try {
      const res = await axiosClient.get<SuccessResponse<AdminUserProfile>>(
        "/api/admin/core/v1/users/me/profile"
      );
      const data = res.data.data;
      setProfile(data);
      if (data.themeKey) setThemeKey(data.themeKey);
      if (data.language) setLanguage(data.language);
      if (data.extensions?.tableDensity) setTableDensity(data.extensions.tableDensity);
    } catch (err: any) {
      const message = err?.response?.data?.message || "Failed to load profile.";
      setError(message);
      toast.error(lang === "ar" ? "فشل تحميل الملف الشخصي" : "Profile Load Failed", message);
    } finally {
      setIsLoading(false);
    }
  }, [lang, toast]);

  useEffect(() => {
    queueMicrotask(() => loadMyProfile());
  }, [loadMyProfile]);

  const hasChanges = useMemo(() => {
    if (!profile) return false;
    return (
      themeKey !== (profile.themeKey || "dark") ||
      language !== (profile.language || "en") ||
      tableDensity !== (profile.extensions?.tableDensity || "compact")
    );
  }, [profile, themeKey, language, tableDensity]);

  const saveProfile = async () => {
    if (isSaving) return;
    setIsSaving(true);
    setError(null);

    try {
      const payload = {
        themeKey,
        language,
        extensions: {
          ...profile?.extensions,
          tableDensity,
        },
      };

      const res = await axiosClient.patch<SuccessResponse<AdminUserProfile>>(
        "/api/admin/core/v1/users/me/profile",
        payload
      );

      const updated = res.data.data;
      setProfile(updated);

      if (language === "ar" || language === "en") {
        setLang(language);
      }

      toast.success(
        lang === "ar" ? "تم الحفظ" : "Preferences Saved",
        lang === "ar"
          ? "تم تحديث تفضيلات الحساب الشخصي بنجاح."
          : "Your profile preferences have been updated."
      );
    } catch (err: any) {
      const msg = err?.response?.data?.message || "Failed to update profile.";
      setError(msg);
      toast.error(lang === "ar" ? "خطأ في الحفظ" : "Save Error", msg);
    } finally {
      setIsSaving(false);
    }
  };

  return {
    lang,
    profile,
    themeKey,
    setThemeKey,
    language,
    setLanguage,
    tableDensity,
    setTableDensity,
    isLoading,
    isSaving,
    error,
    hasChanges,
    saveProfile,
    reload: loadMyProfile,
  };
}

"use client";

import { useState, useEffect, useCallback } from "react";
import { useI18n } from "@/i18n/I18nContext";
import { axiosClient } from "@/lib/api/axiosClient";
import { SuccessResponse } from "@/types/common";

import { useHasPermission } from "@/components/auth/RequirePermission";

export interface SmtpConfigState {
  fromAddress: string;
  fromName: string;
  senderDomain: string;
  smtpHost: string;
  smtpPort: number;
  smtpSecure: boolean;
  smtpProtocol: "smtp" | "smtps";
  smtpUsername: string;
  smtpPasswordConfigured: boolean;
  configured: boolean;
  revision?: number | null;
  updatedAt?: string | null;
}

export interface SmtpAuditChange {
  field: string;
  label: string;
  previousValue: any;
  newValue: any;
}

export interface SmtpAuditLog {
  id: string;
  action: "CONFIGURED" | "UPDATED" | "CONNECTION_VERIFIED";
  revision: number | null;
  actor: string;
  changes: SmtpAuditChange[];
  createdAt: string;
}

export function useSmtpSettings() {
  const { lang } = useI18n();
  const hasUpdatePermission = useHasPermission("admin.settings.update");

  const [config, setConfig] = useState<SmtpConfigState>({
    fromAddress: "",
    fromName: "",
    senderDomain: "",
    smtpHost: "",
    smtpPort: 587,
    smtpSecure: true,
    smtpProtocol: "smtps",
    smtpUsername: "",
    smtpPasswordConfigured: false,
    configured: false,
  });

  const [auditLogs, setAuditLogs] = useState<SmtpAuditLog[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [isSaving, setIsSaving] = useState(false);
  const [lastSaved, setLastSaved] = useState<Date | null>(null);

  const [isVerifying, setIsVerifying] = useState(false);

  const fetchConfig = useCallback(async () => {
    setIsLoading(true);
    try {
      const [configRes, auditRes] = await Promise.all([
        axiosClient.get<SuccessResponse<any>>(`/api/admin/core/v1/system-settings/email`),
        axiosClient.get<SuccessResponse<SmtpAuditLog[]>>(`/api/admin/core/v1/system-settings/email/audit`),
      ]);

      if (configRes.data && configRes.data.success) {
        const data = configRes.data.data;
        setConfig({
          fromAddress: data.fromAddress || "",
          fromName: data.fromName || "",
          senderDomain: data.senderDomain || "",
          smtpHost: data.smtpHost || "",
          smtpPort: data.smtpPort || 587,
          smtpSecure: Boolean(data.smtpSecure),
          smtpProtocol: data.smtpProtocol || "smtp",
          smtpUsername: data.smtpUsername || "",
          smtpPasswordConfigured: Boolean(data.smtpPasswordConfigured),
          configured: Boolean(data.configured),
          revision: data.revision,
          updatedAt: data.updatedAt,
        });
      }

      if (auditRes.data && auditRes.data.success) {
        setAuditLogs(auditRes.data.data);
      }
    } catch (err) {
      console.error("Failed to fetch SMTP settings or audit logs", err);
      setAuditLogs([]);
    } finally {
      setIsLoading(false);
    }
  }, []);

  useEffect(() => {
    queueMicrotask(() => fetchConfig());
  }, [fetchConfig]);

  const handleUpdate = (field: keyof SmtpConfigState, value: any) => {
    setConfig((prev) => ({ ...prev, [field]: value }));
  };

  const saveConfig = async (password?: string) => {
    setIsSaving(true);

    const payload: Record<string, any> = {
      fromAddress: config.fromAddress,
      fromName: config.fromName,
      senderDomain: config.senderDomain,
      smtpHost: config.smtpHost,
      smtpPort: config.smtpPort,
      smtpSecure: config.smtpSecure,
      smtpProtocol: config.smtpProtocol,
      smtpUsername: config.smtpUsername,
    };

    if (password) {
      payload.smtpPassword = password;
    }

    try {
      const res = await axiosClient.patch<SuccessResponse<any>>(
        `/api/admin/core/v1/system-settings/email`,
        payload
      );

      const updated = res.data.data;
      setConfig((prev) => ({
        ...prev,
        smtpPasswordConfigured: Boolean(updated.smtpPasswordConfigured),
        revision: updated.revision,
        configured: Boolean(updated.configured),
      }));
      setLastSaved(new Date());
      fetchConfig();
    } catch (err: any) {
      let msg = "Failed to save SMTP configuration";
      if (err?.response?.data) {
        msg = err.response.data.message || err.response.data.title || err.response.data.detail || msg;
      }
      throw new Error(msg);
    } finally {
      setIsSaving(false);
    }
  };

  const verifyConnection = async () => {
    setIsVerifying(true);
    try {
      await axiosClient.post<SuccessResponse<any>>(
        `/api/admin/core/v1/system-settings/email/verify-connection`,
        undefined // Explicitly no body
      );

      fetchConfig();
    } catch (err: any) {
      let msg = "Connection verification failed";
      if (err?.response?.data) {
        msg = err.response.data.message || err.response.data.title || err.response.data.detail || msg;
      }
      throw new Error(msg);
    } finally {
      setIsVerifying(false);
    }
  };

  return {
    lang,
    config,
    auditLogs,
    isLoading,
    isSaving,
    lastSaved,
    handleUpdate,
    saveConfig,
    verifyConnection,
    isVerifying,
    refetch: fetchConfig,
    hasUpdatePermission,
  };
}

import { useCallback, useEffect, useState } from "react";
import { useAuth } from "@/context/AuthContext";
import {
  getStorageServer,
  updateStorageServer,
  activateStorageServer,
  offlineStorageServer,
  deleteStorageServer,
} from "../api/storageServersApi";
import type { StorageServerView, UpdateStorageServerDto } from "@/types/storage-server";
import { adminCan, adminCanAll, ADMIN_RBAC_CRITICAL } from "@/lib/auth/rbac";

export function useStorageServerDetail(id: string | null) {
  const { user } = useAuth();

  const [server, setServer] = useState<StorageServerView | null>(null);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState<any>(null);

  const fetchServer = useCallback(async () => {
    if (!user || !id) return;
    setIsLoading(true);
    setError(null);
    try {
      const data = await getStorageServer(id);
      setServer(data);
    } catch (err: any) {
      setError(err);
    } finally {
      setIsLoading(false);
    }
  }, [user, id]);

  useEffect(() => {
    queueMicrotask(() => fetchServer());
  }, [fetchServer]);

  // RBAC checks
  const canRead = user ? adminCan(user, "admin.storage_servers.read") : false;

  const canUpdate = user
    ? adminCanAll(user, ADMIN_RBAC_CRITICAL.STORAGE_SERVERS_UPDATE)
    : false;

  const canDelete = user
    ? adminCanAll(user, ADMIN_RBAC_CRITICAL.STORAGE_SERVERS_DELETE)
    : false;

  const handleUpdate = useCallback(
    async (dto: UpdateStorageServerDto) => {
      if (!canUpdate || !id) throw new Error("Missing permissions or ID");
      const updated = await updateStorageServer(id, dto);
      setServer(updated);
      return updated;
    },
    [id, canUpdate]
  );

  const handleActivate = useCallback(async () => {
    if (!canUpdate || !id) throw new Error("Missing permissions or ID");
    try {
      const updated = await activateStorageServer(id);
      setServer(updated);
      return updated;
    } catch (err: any) {
      // Refresh the server state to capture lastConnectionTestErrorCode from the backend
      await fetchServer();
      throw err;
    }
  }, [id, canUpdate, fetchServer]);

  const handleOffline = useCallback(async () => {
    if (!canUpdate || !id) throw new Error("Missing permissions or ID");
    const updated = await offlineStorageServer(id);
    setServer(updated);
    return updated;
  }, [id, canUpdate]);

  const handleDelete = useCallback(async () => {
    if (!canDelete || !id) throw new Error("Missing permissions or ID");
    await deleteStorageServer(id);
  }, [id, canDelete]);

  const handleMakePlatformDefault = useCallback(async () => {
    if (!canUpdate || !id) throw new Error("Missing permissions or ID");
    const updated = await updateStorageServer(id, { isPlatformDefault: true });
    setServer(updated);
    return updated;
  }, [id, canUpdate]);

  return {
    server,
    isLoading,
    error,
    canRead,
    canUpdate,
    canDelete,
    handleUpdate,
    handleActivate,
    handleOffline,
    handleDelete,
    handleMakePlatformDefault,
    refresh: fetchServer,
  };
}

import { useCallback, useEffect, useState } from "react";
import { useAuth } from "@/context/AuthContext";
import { listStorageServers, createStorageServer } from "../api/storageServersApi";
import type { StorageServerView, StorageServerList, StorageServerStatus, CreateStorageServerDto } from "@/types/storage-server";
import { adminCan, adminCanAll, ADMIN_RBAC_CRITICAL } from "@/lib/auth/rbac";

export function useStorageServers() {
  const { user } = useAuth();

  const [page, setPage] = useState(1);
  const [limit, setLimit] = useState(10);
  const [search, setSearch] = useState("");
  const [status, setStatus] = useState("ALL");

  const [servers, setServers] = useState<StorageServerView[]>([]);
  const [totalItems, setTotalItems] = useState(0);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState<any>(null);

  const fetchData = useCallback(async () => {
    if (!user) return;
    setIsLoading(true);
    setError(null);
    try {
      const res = await listStorageServers({
        page,
        limit,
        search,
        status,
        sortBy: "createdAt",
        sortDir: "DESC",
      });
      setServers(res.items);
      setTotalItems(res.total);
    } catch (err: any) {
      setError(err);
    } finally {
      setIsLoading(false);
    }
  }, [user, page, limit, search, status]);

  useEffect(() => {
    queueMicrotask(() => fetchData());
  }, [fetchData]);

  const canRead = user ? adminCan(user, "admin.storage_servers.read") : false;

  // Create requires base create + critical
  const canCreate = user
    ? adminCanAll(user, ADMIN_RBAC_CRITICAL.STORAGE_SERVERS_CREATE)
    : false;

  const handleCreate = useCallback(
    async (dto: CreateStorageServerDto) => {
      if (!canCreate) throw new Error("Missing permissions to create storage server");
      const newServer = await createStorageServer(dto);
      await fetchData();
      return newServer;
    },
    [canCreate, fetchData]
  );

  return {
    servers,
    totalItems,
    isLoading,
    error,
    page,
    setPage,
    limit,
    setLimit,
    search,
    setSearch,
    status,
    setStatus,
    canRead,
    canCreate,
    handleCreate,
    refresh: fetchData,
  };
}

"use client";

import { useCallback, useEffect, useMemo, useState } from "react";
import { useRouter } from "next/navigation";
import { useI18n } from "@/i18n/I18nContext";
import { useToast } from "@/components/ui/ToastContext";
import {
  getAdminUser,
  getUserWebphone,
  listRoles,
  updateAdminUser,
  assignUserRole,
  updateUserWebphone,
  suspendAdminUser,
  activateAdminUser,
  deleteAdminUser,
  normalizeErrorCode,
} from "../api/adminUsersApi";
import { getErrorMessageAndDetails, type MappedErrorDetails } from "../utils/errorMapping";
import type {
  AdminUser,
  AdminRole,
  AdminWebphoneConfig,
  AdminUserStatus,
} from "../types";

export type WebphoneForm = {
  enabled: boolean;
  extension: string;
  sipUsername: string;
  sipPassword: string;
  displayName: string;
  outboundCallerId: string;
  transport: "ws" | "wss";
};

const emptyWebphoneForm: WebphoneForm = {
  enabled: false,
  extension: "",
  sipUsername: "",
  sipPassword: "",
  displayName: "",
  outboundCallerId: "",
  transport: "wss",
};

function toastErrorMessage(details: MappedErrorDetails) {
  return details.correlationId
    ? `${details.message}\nCorrelation ID: ${details.correlationId}`
    : details.message;
}

export function useUserDetail(id: string) {
  const router = useRouter();
  const { lang, t } = useI18n();
  const toast = useToast();

  const [user, setUser] = useState<AdminUser>();
  const [availableRoles, setAvailableRoles] = useState<AdminRole[]>([]);
  const [assignedRoleId, setAssignedRoleId] = useState<string | undefined>();
  const [firstName, setFirstName] = useState("");
  const [lastName, setLastName] = useState("");
  const [isSuperAdmin, setIsSuperAdmin] = useState<boolean>(false);
  const [status, setStatus] = useState<AdminUserStatus>("INVITED");

  const [webphone, setWebphone] = useState<AdminWebphoneConfig>();
  const [webphoneForm, setWebphoneForm] = useState<WebphoneForm>(emptyWebphoneForm);

  const [isLoading, setIsLoading] = useState(true);
  const [isSaving, setIsSaving] = useState(false);
  const [notFound, setNotFound] = useState(false);
  const [permissionDenied, setPermissionDenied] = useState(false);

  const [extensionError, setExtensionError] = useState<string | null>(null);
  const [sipUsernameError, setSipUsernameError] = useState<string | null>(null);

  const loadUser = useCallback(async () => {
    setIsLoading(true);
    setNotFound(false);
    setPermissionDenied(false);

    try {
      const [loadedUser, loadedWebphone, rolesData] = await Promise.all([
        getAdminUser(id),
        getUserWebphone(id).catch(() => undefined),
        listRoles({ page: 1, limit: 100, sortBy: "name", sortDir: "ASC" }).catch(() => undefined),
      ]);

      const assignedRoles = loadedUser.role ? [loadedUser.role] : [];
      const rolesList = rolesData?.data ?? assignedRoles;

      setUser(loadedUser);
      setFirstName(loadedUser.firstName);
      setLastName(loadedUser.lastName);
      setIsSuperAdmin(loadedUser.isSuperAdmin);
      setStatus(loadedUser.status);
      setAvailableRoles(rolesList);
      setAssignedRoleId(loadedUser.roleId ?? loadedUser.role?.id ?? undefined);

      if (loadedWebphone) {
        setWebphone(loadedWebphone);
        setWebphoneForm(webphoneFormFromConfig(loadedWebphone));
      }
    } catch (requestError: any) {
      const code = normalizeErrorCode(requestError);

      if (requestError?.response?.status === 404 || code === "ADMIN_USER_NOT_FOUND") {
        setNotFound(true);
      } else if (requestError?.response?.status === 403 || code === "MISSING_REQUIRED_PERMISSIONS") {
        setPermissionDenied(true);
      } else {
        const details = getErrorMessageAndDetails(requestError, lang);
        toast.error(lang === "ar" ? "فشل التحميل" : "Load Error", toastErrorMessage(details));
      }
    } finally {
      setIsLoading(false);
    }
  }, [id, lang, toast]);

  useEffect(() => {
    queueMicrotask(() => loadUser());
  }, [loadUser]);

  const identityHasChanges = useMemo(() => {
    if (!user) return false;
    return (
      firstName.trim() !== user.firstName ||
      lastName.trim() !== user.lastName ||
      isSuperAdmin !== user.isSuperAdmin
    );
  }, [user, firstName, lastName, isSuperAdmin]);

  const roleHasChanges = useMemo(() => {
    if (!user) return false;
    return (assignedRoleId ?? null) !== (user.roleId ?? null);
  }, [user, assignedRoleId]);

  const webphoneHasChanges = useMemo(
    () => webphoneFormChanged(webphoneForm, webphone),
    [webphone, webphoneForm]
  );

  const saveIdentity = async () => {
    if (!user || !identityHasChanges || isSaving) return;
    if (!firstName.trim() || !lastName.trim()) {
      const msg = lang === "ar" ? "الاسم الأول واسم العائلة مطلوبان." : "First name and last name are required.";
      toast.error(lang === "ar" ? "حقل مطلوب" : "Required Field", msg);
      return;
    }

    setIsSaving(true);

    try {
      const updated = await updateAdminUser(user.id, {
        firstName: firstName.trim() !== user.firstName ? firstName.trim() : undefined,
        lastName: lastName.trim() !== user.lastName ? lastName.trim() : undefined,
        isSuperAdmin: isSuperAdmin !== user.isSuperAdmin ? isSuperAdmin : undefined,
      });

      setUser(updated);
      setFirstName(updated.firstName);
      setLastName(updated.lastName);
      setIsSuperAdmin(updated.isSuperAdmin);
      toast.success(
        lang === "ar" ? "تم الحفظ" : "Saved",
        lang === "ar" ? "تم تحديث البيانات الشخصية بنجاح." : "Identity profile updated successfully."
      );
    } catch (requestError: any) {
      const details = getErrorMessageAndDetails(requestError, lang);
      toast.error(lang === "ar" ? "خطأ في الحفظ" : "Save Error", toastErrorMessage(details));

      setFirstName(user.firstName);
      setLastName(user.lastName);
      setIsSuperAdmin(user.isSuperAdmin);
    } finally {
      setIsSaving(false);
    }
  };

  const saveRole = async () => {
    if (!user || !roleHasChanges || !assignedRoleId || isSaving) return;

    setIsSaving(true);

    try {
      await assignUserRole(user.id, { roleId: assignedRoleId });
      const freshUser = await getAdminUser(user.id);

      setUser(freshUser);
      setAssignedRoleId(freshUser.roleId ?? freshUser.role?.id ?? undefined);
      toast.success(
        lang === "ar" ? "تم تعيين الدور" : "Role Assigned",
        lang === "ar"
          ? "تم تحديث دور المشرف بنجاح وتم إبطال الجلسات السابقة."
          : "Role updated successfully. Active sessions have been invalidated."
      );
    } catch (requestError: any) {
      const details = getErrorMessageAndDetails(requestError, lang);
      toast.error(lang === "ar" ? "خطأ في الحفظ" : "Save Error", toastErrorMessage(details));

      setAssignedRoleId(user.roleId ?? user.role?.id ?? undefined);
    } finally {
      setIsSaving(false);
    }
  };

  const saveWebphone = async () => {
    if (!user || !webphoneHasChanges || isSaving) return;

    const validationError = validateWebphoneForm(webphoneForm, webphone, lang);
    if (validationError) {
      toast.error(lang === "ar" ? "خطأ في التحقق" : "Validation Error", validationError);
      return;
    }

    setIsSaving(true);
    setExtensionError(null);
    setSipUsernameError(null);

    try {
      const payload = webphonePayloadFromForm(webphoneForm);
      const updated = await updateUserWebphone(user.id, payload);

      setWebphone(updated);
      setWebphoneForm(webphoneFormFromConfig(updated));
      toast.success(
        lang === "ar" ? "تم حفظ إعدادات الهاتف" : "Phone Settings Saved",
        lang === "ar" ? "تم تحديث إعدادات WebPhone بنجاح." : "WebPhone configuration updated successfully."
      );
    } catch (requestError: any) {
      const details = getErrorMessageAndDetails(requestError, lang);
      if (details.fieldErrors?.extension) setExtensionError(details.fieldErrors.extension);
      if (details.fieldErrors?.sipUsername) setSipUsernameError(details.fieldErrors.sipUsername);

      toast.error(lang === "ar" ? "خطأ في الحفظ" : "Save Error", toastErrorMessage(details));
    } finally {
      setIsSaving(false);
    }
  };

  const handleStatusChange = async (nextStatus: "ACTIVE" | "SUSPENDED") => {
    if (!user || isSaving) return;

    setIsSaving(true);

    try {
      const updated =
        nextStatus === "ACTIVE" ? await activateAdminUser(user.id) : await suspendAdminUser(user.id);

      setUser(updated);
      setStatus(updated.status);
      toast.success(
        lang === "ar" ? "نجاح" : "Success",
        lang === "ar" ? "تم تحديث حالة المستخدم بنجاح." : "User status updated successfully."
      );
    } catch (requestError: any) {
      const details = getErrorMessageAndDetails(requestError, lang);
      toast.error(lang === "ar" ? "خطأ في التحديث" : "Update Error", toastErrorMessage(details));
    } finally {
      setIsSaving(false);
    }
  };

  const handleDelete = async () => {
    if (!user || isSaving) return;

    setIsSaving(true);

    try {
      await deleteAdminUser(user.id);
      toast.success(
        lang === "ar" ? "تم الحذف" : "Deleted",
        lang === "ar" ? "تم حذف حساب المشرف بنجاح." : "Admin user deleted successfully."
      );
      router.push("/users");
    } catch (requestError: any) {
      const details = getErrorMessageAndDetails(requestError, lang);
      toast.error(lang === "ar" ? "خطأ في الحذف" : "Delete Error", toastErrorMessage(details));
    } finally {
      setIsSaving(false);
    }
  };

  return {
    lang,
    t,
    router,
    user,
    isLoading,
    isSaving,
    notFound,
    permissionDenied,
    reload: loadUser,

    firstName,
    setFirstName,
    lastName,
    setLastName,
    email: user?.email ?? "",
    isSuperAdmin,
    setIsSuperAdmin,
    assignedRoleId,
    setAssignedRoleId,
    availableRoles,
    status,

    identityHasChanges,
    roleHasChanges,
    webphoneHasChanges,

    webphoneEnabled: webphoneForm.enabled,
    setWebphoneEnabled: (enabled: boolean) =>
      setWebphoneForm((current) => ({ ...current, enabled })),
    sipExtension: webphoneForm.extension,
    setSipExtension: (extension: string) => {
      setExtensionError(null);
      setWebphoneForm((current) => ({ ...current, extension }));
    },
    sipUsername: webphoneForm.sipUsername,
    setSipUsername: (sipUsername: string) => {
      setSipUsernameError(null);
      setWebphoneForm((current) => ({ ...current, sipUsername }));
    },
    sipPassword: webphoneForm.sipPassword,
    setSipPassword: (sipPassword: string) =>
      setWebphoneForm((current) => ({ ...current, sipPassword })),
    webphoneDisplayName: webphoneForm.displayName,
    setWebphoneDisplayName: (displayName: string) =>
      setWebphoneForm((current) => ({ ...current, displayName })),
    outboundCallerId: webphoneForm.outboundCallerId,
    setOutboundCallerId: (outboundCallerId: string) =>
      setWebphoneForm((current) => ({ ...current, outboundCallerId })),
    webphoneTransport: webphoneForm.transport,
    setWebphoneTransport: (transport: "ws" | "wss") =>
      setWebphoneForm((current) => ({ ...current, transport })),
    passwordConfigured: Boolean(webphone?.passwordConfigured),

    webphoneConfig: webphone,
    extensionError,
    sipUsernameError,

    saveIdentity,
    saveRole,
    saveWebphone,
    handleStatusChange,
    handleDelete,
  };
}

function webphoneFormFromConfig(config?: AdminWebphoneConfig | null): WebphoneForm {
  return {
    enabled: Boolean(config?.enabled),
    extension: config?.extension ?? "",
    sipUsername: config?.sipUsername ?? "",
    sipPassword: "",
    displayName: config?.displayName ?? "",
    outboundCallerId: config?.outboundCallerId ?? "",
    transport: config?.transport === "ws" ? "ws" : "wss",
  };
}

function webphonePayloadFromForm(form: WebphoneForm) {
  return {
    enabled: form.enabled,
    extension: nullableText(form.extension),
    sipUsername: nullableText(form.sipUsername),
    ...(form.sipPassword.trim() ? { sipPassword: form.sipPassword.trim() } : {}),
    displayName: nullableText(form.displayName),
    outboundCallerId: nullableText(form.outboundCallerId),
    transport: form.transport,
  };
}

function webphoneFormChanged(form: WebphoneForm, config?: AdminWebphoneConfig | null) {
  const baseline = webphoneFormFromConfig(config);
  return (
    form.enabled !== baseline.enabled ||
    form.extension.trim() !== baseline.extension ||
    form.sipUsername.trim() !== baseline.sipUsername ||
    Boolean(form.sipPassword.trim()) ||
    form.displayName.trim() !== baseline.displayName ||
    form.outboundCallerId.trim() !== baseline.outboundCallerId ||
    form.transport !== baseline.transport
  );
}

function validateWebphoneForm(
  form: WebphoneForm,
  config: AdminWebphoneConfig | undefined,
  lang: "ar" | "en"
) {
  if (!form.enabled) return undefined;
  if (!form.extension.trim() || !form.sipUsername.trim()) {
    return lang === "ar"
      ? "تفعيل WebPhone يتطلب رقم الامتداد واسم مستخدم SIP."
      : "Enabled WebPhone settings require an extension and SIP username.";
  }
  if (!form.sipPassword.trim() && !config?.passwordConfigured) {
    return lang === "ar"
      ? "تفعيل WebPhone يتطلب كلمة مرور SIP."
      : "Enabled WebPhone settings require a SIP password.";
  }
  return undefined;
}

function nullableText(value: string) {
  const trimmed = value.trim();
  return trimmed || null;
}

"use client";

import { useState, useEffect, useCallback } from "react";
import { useRouter } from "next/navigation";
import { useI18n } from "@/i18n/I18nContext";
import { useToast } from "@/components/ui/ToastContext";
import { useAuth } from "@/context/AuthContext";
import {
  listAdminUsers,
  listRoles,
  suspendAdminUser,
  activateAdminUser,
  deleteAdminUser,
  normalizeErrorCode,
} from "../api/adminUsersApi";
import { getErrorMessageAndDetails } from "../utils/errorMapping";
import type { AdminUser, AdminRole, AdminUserErrorCode } from "../types";

export function useUsers() {
  const router = useRouter();
  const { lang, t } = useI18n();
  const toast = useToast();
  const { user: currentUser } = useAuth();

  const [search, setSearch] = useState("");
  const [debouncedSearch, setDebouncedSearch] = useState("");
  const [statusFilter, setStatusFilter] = useState("ALL");
  const [roleFilter, setRoleFilter] = useState("ALL");
  const [isSuperAdminFilter, setIsSuperAdminFilter] = useState("ALL");
  const [sortBy, setSortBy] = useState("createdAt");
  const [sortDir, setSortDir] = useState("DESC");
  const [page, setPage] = useState(1);
  const [limit, setLimit] = useState(20);

  const [users, setUsers] = useState<AdminUser[]>([]);
  const [roles, setRoles] = useState<AdminRole[]>([]);
  const [rolesForbidden, setRolesForbidden] = useState(false);
  const [totalPages, setTotalPages] = useState(1);
  const [totalCount, setTotalCount] = useState(0);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [errorCode, setErrorCode] = useState<AdminUserErrorCode | string | null>(null);
  const [permissionDenied, setPermissionDenied] = useState(false);

  // Modals state
  const [isInviteModalOpen, setIsInviteModalOpen] = useState(false);
  const [activeModalUserId, setActiveModalUserId] = useState<string | null>(null);
  const [modalActionType, setModalActionType] = useState<"suspend" | "activate" | "delete" | null>(null);
  const [isActionLoading, setIsActionLoading] = useState(false);

  const [summaryMetrics, setSummaryMetrics] = useState({
    total: 0,
    active: 0,
    invited: 0,
    suspended: 0,
    superAdmins: 0,
  });

  // Debounce search
  useEffect(() => {
    const handler = setTimeout(() => {
      setDebouncedSearch(search);
      queueMicrotask(() => setPage(1));
    }, 500);
    return () => clearTimeout(handler);
  }, [search]);

  // Reset page on filter change
  useEffect(() => {
    setPage(1);
  }, [statusFilter, roleFilter, isSuperAdminFilter, sortBy, sortDir, limit]);

  // Fetch roles for filter dropdown
  useEffect(() => {
    async function loadRolesData() {
      try {
        setRolesForbidden(false);
        const res = await listRoles({ page: 1, limit: 100, sortBy: "name", sortDir: "ASC" });
        const items = res?.data;
        if (Array.isArray(items)) {
          setRoles(items);
        } else if ((items as any)?.items) {
          setRoles((items as any).items);
        }
      } catch (err: any) {
        if (err?.response?.status === 403) {
          setRolesForbidden(true);
        }
      }
    }
    loadRolesData();
  }, []);

  const fetchUsers = useCallback(async () => {
    setIsLoading(true);
    setError(null);
    setErrorCode(null);
    setPermissionDenied(false);

    try {
      const res = await listAdminUsers({
        page,
        limit,
        search: debouncedSearch || undefined,
        status: statusFilter,
        isSuperAdmin: isSuperAdminFilter,
        roleId: roleFilter,
        sortBy,
        sortDir,
      });

      const responseData = res?.data;
      const meta = res?.meta;

      const userList = Array.isArray(responseData) ? responseData : ((responseData as any)?.items || []);
      setUsers(userList);

      const total = meta?.total ?? (responseData as any)?.meta?.total ?? userList.length;
      const totalPgs = meta?.totalPages ?? (responseData as any)?.meta?.totalPages ?? 1;

      setTotalCount(total);
      setTotalPages(totalPgs);

      // Derive metrics accurately
      const activeCount = userList.filter((u: AdminUser) => u.status === "ACTIVE").length;
      const invitedCount = userList.filter((u: AdminUser) => u.status === "INVITED").length;
      const suspendedCount = userList.filter((u: AdminUser) => u.status === "SUSPENDED").length;
      const superAdminCount = userList.filter((u: AdminUser) => u.isSuperAdmin).length;

      setSummaryMetrics({
        total,
        active: activeCount,
        invited: invitedCount,
        suspended: suspendedCount,
        superAdmins: superAdminCount,
      });
    } catch (err: any) {
      const code = normalizeErrorCode(err);
      setErrorCode(code);

      if (err?.response?.status === 403) {
        setPermissionDenied(true);
      } else {
        const details = getErrorMessageAndDetails(err, lang);
        setError(details.message);
        toast.error(
          lang === "ar" ? "خطأ في التحميل" : "Load Error",
          details.message
        );
      }
    } finally {
      setIsLoading(false);
    }
  }, [page, limit, debouncedSearch, statusFilter, roleFilter, isSuperAdminFilter, sortBy, sortDir, lang, toast]);

  useEffect(() => {
    queueMicrotask(() => {
      fetchUsers();
    });
  }, [fetchUsers]);

  const activeModalUser = users.find((u) => u.id === activeModalUserId);

  const openModal = (userId: string, action: "suspend" | "activate" | "delete") => {
    if (currentUser?.id === userId) {
      toast.error(
        lang === "ar" ? "إجراء غير مسموح" : "Forbidden Action",
        lang === "ar" ? "لا يمكنك إجاء هذه العملية على حسابك الخاص." : "You cannot perform this action on your own account."
      );
      return;
    }
    setActiveModalUserId(userId);
    setModalActionType(action);
  };

  const closeModal = () => {
    if (isActionLoading) return;
    setActiveModalUserId(null);
    setModalActionType(null);
  };

  const confirmModalAction = async () => {
    if (!activeModalUserId || !modalActionType) return;

    setIsActionLoading(true);
    try {
      if (modalActionType === "delete") {
        await deleteAdminUser(activeModalUserId);
        toast.success(
          lang === "ar" ? "تم الحذف" : "Deleted",
          lang === "ar" ? "تم حذف المستخدم بنجاح" : "User deleted successfully"
        );
      } else if (modalActionType === "suspend") {
        await suspendAdminUser(activeModalUserId);
        toast.success(
          lang === "ar" ? "تم التعليق" : "Suspended",
          lang === "ar" ? "تم تعليق حساب المستخدم بنجاح" : "User suspended successfully"
        );
      } else if (modalActionType === "activate") {
        await activateAdminUser(activeModalUserId);
        toast.success(
          lang === "ar" ? "تم التنشيط" : "Activated",
          lang === "ar" ? "تم تنشيط حساب المستخدم بنجاح" : "User activated successfully"
        );
      }

      closeModal();
      fetchUsers();
    } catch (err: any) {
      const details = getErrorMessageAndDetails(err, lang);
      toast.error(
        lang === "ar" ? "فشل الإجراء" : "Action Failed",
        details.message
      );
    } finally {
      setIsActionLoading(false);
    }
  };

  return {
    lang,
    t,
    router,
    search,
    setSearch,
    statusFilter,
    setStatusFilter,
    roleFilter,
    setRoleFilter,
    isSuperAdminFilter,
    setIsSuperAdminFilter,
    sortBy,
    setSortBy,
    sortDir,
    setSortDir,
    page,
    setPage,
    limit,
    setLimit,
    totalPages,
    totalCount,
    isLoading,
    error,
    errorCode,
    permissionDenied,
    rolesForbidden,
    users,
    roles,
    summaryMetrics,
    isInviteModalOpen,
    setIsInviteModalOpen,
    activeModalUser,
    modalActionType,
    openModal,
    closeModal,
    confirmModalAction,
    isActionLoading,
    refresh: fetchUsers,
  };
}

